def sha(raw):
    return hashlib.sha256(raw).hexdigest()


def free(path):
    s = os.statvfs(path)
    return s.f_bavail * s.f_frsize


def git(*args, timeout=60, allow_error=False):
    p = subprocess.run(['sudo', '-u', 'ubuntu', '-H', 'git', '-c', 'gc.auto=0',
                        '-c', 'maintenance.auto=false', '-C', str(ROOT), *args],
                       capture_output=True, timeout=timeout)
    if p.returncode and not allow_error:
        raise RuntimeError((args, p.returncode, p.stderr.decode(errors='replace')[:2500]))
    return p if allow_error else p.stdout


def checked_leaf(path, limit):
    assert path.resolve(strict=True) == path
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
    try:
        before = os.fstat(fd)
        assert stat.S_ISREG(before.st_mode) and before.st_nlink == 1 and before.st_size <= limit
        with os.fdopen(os.dup(fd), 'rb') as f:
            raw = f.read(limit + 1)
        after = os.fstat(fd)
        assert len(raw) == before.st_size
        assert (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns, before.st_ctime_ns) == (
            after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns, after.st_ctime_ns)
        assert path.lstat().st_ino == before.st_ino
        return raw
    finally:
        os.close(fd)


def write_new(path, raw):
    path.parent.mkdir(parents=True, exist_ok=True)
    assert path.parent.resolve(strict=True) == path.parent
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o644)
    try:
        pos = 0
        while pos < len(raw):
            n = os.write(fd, raw[pos:]); assert n > 0; pos += n
        os.fchown(fd, 1001, 1001)
        os.fsync(fd)
    finally:
        os.close(fd)
    assert checked_leaf(path, len(raw)) == raw


